# Копія fuel.water.WATER_WORD: міграція не залежить від коду застосунку
WATER_WORD = re.compile(r"(?<![^\W\d_])вод[аиу](?![^\W\d_])", re.IGNORECASE)


def mark_water_cards(apps, schema_editor):
    """Одноразово позначає наявні картки Petroline зі словом «вода» в назві (Petroline або наші Авто/ПІБ)."""
    Card = apps.get_model("fuel", "Card")
    ids = [
        card.pk
        for card in Card.objects.filter(provider="petroline").only("provider_label", "vehicle", "driver_name")
        if any(WATER_WORD.search(text or "") for text in (card.provider_label, card.vehicle, card.driver_name))
    ]
    Card.objects.filter(pk__in=ids).update(is_water=True)


